-- The guild map, live (#449)
L["Share my position with the guild"] = "与公会共享我的位置"
L["Only while a guildmate has the guild map open; never coordinates in an instance, nothing in combat there."] = "仅在有公会成员打开地图时；副本内从不发送坐标，副本战斗中什么都不发送。"
L["Guildmates on this map (%d)"] = "此地图上的公会成员 (%d)"
L["Elsewhere (%d)"] = "其他地方 (%d)"
L["In an instance: %s"] = "在副本中：%s"
L["Updated %d s ago"] = "%d 秒前更新"
L["In your group"] = "在你的队伍中"
L["You are not sharing your position (Settings > Privacy)."] = "你没有共享自己的位置（设置 > 隐私）。"
L["This client's map gives no positions: guildmates are listed, not drawn."] = "此客户端的地图不提供位置：公会成员只列出，不绘制。"
L["No guildmate on this map."] = "此地图上没有公会成员。"
L["Only guildmates with Guild OS who share their position, and your group, show here."] = "这里只显示使用 Guild OS 并共享位置的公会成员，以及你的队伍。"
L["Level %d %s"] = "%d级 %s"
L["%d yd"] = "%d码"
L["The attributes did not come through: the game hides them on this client while it restricts data (WoW: Forever). They fill in when the member syncs without that restriction."] = "属性未能传来：该客户端在限制数据时会隐藏属性（WoW: Forever）。成员在无此限制时同步后会显示。"
L["Write {name} where the new member's name goes, and {guild} for the guild's name."] = "在新成员名字的位置写 {name}，公会名写 {guild}。"

-- The guild map and OpenMap (#449)
L["Shared through OpenMap"] = "通过 OpenMap 共享"
L["In this zone by the roster, no position (%d)"] = "名单显示在此区域，无位置 (%d)"
L["OpenMap draws guildmates too: type /openmap and, on its \"On the map\" tab, turn off \"Guild members on the map\"."] = "OpenMap 也会显示公会成员：输入 /openmap，在“地图显示”标签中关闭“地图上的公会成员”。"
L["Only guildmates who share their position (with Guild OS, or OpenMap's sharing), and your group, show here."] = "这里只显示共享位置的公会成员（通过 Guild OS 或 OpenMap 的共享）和你的队伍。"
L["OpenMap shows guildmates too"] = "OpenMap 也显示公会成员"
L["Got it"] = "知道了"
L["Don't show again"] = "不再显示"
L["OpenMap also draws guild members on the world map, so a guildmate can show twice. Guild OS already shows the guildmates who share their place through OpenMap. To see each once, type /openmap and, on the \"On the map\" tab, turn off \"Guild members on the map\"."] = "OpenMap 也会在世界地图上显示公会成员，同一个人可能出现两次。Guild OS 已经会显示通过 OpenMap 共享位置的成员。要让每人只显示一次，请输入 /openmap，在“地图显示”标签中关闭“地图上的公会成员”。"
L["OpenMap's \"Share where you are\" (its \"More\" tab) sends your place to the guild every few seconds even when nobody looks; Guild OS already shares it while a guildmate has the map open. Keep it on only for friends outside the guild."] = "OpenMap 的“共享你的位置”（“更多”标签）即使没人在看也会每隔几秒把你的位置发给公会；Guild OS 已经会在公会成员打开地图时共享位置。只有公会外的好友需要时才保持开启。"
L["on OpenMap"] = "在 OpenMap 上"
L["Drawn by OpenMap"] = "由 OpenMap 显示"
